import{z as d,x as c,o,c as p,q as n,j as l,D as r,d as t,s as i,S as E,b as e}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"函数式队列","description":"","frontmatter":{"title":"函数式队列","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/functional-queue.md","filePath":"cs/functional-queue.md","lastUpdated":1791413859000}'),B={name:"cs/functional-queue.md"};function A(u,a,f,m,C,D){const s=c("Mermaid");return o(),p("div",null,[a[2]||(a[2]=n('<h1 id="函数式队列" tabindex="-1">函数式队列 <a class="header-anchor" href="#函数式队列" aria-label="Permalink to &quot;函数式队列&quot;">​</a></h1><div class="epigraph"><p>前栈出队、后栈入队；后栈倒进前栈时一次线性，摊还仍 $O(1)$。旧版本的两栈指针保持持久。</p><footer>—— 据 Okasaki, Simple and Efficient Purely Functional Queues and Deques, JFP 1995；Okasaki, Purely Functional Data Structures；Hood and Melville 整理</footer></div><p><a href="/cs/persistent-path-copy">上一课</a> 给了树的复制。<a href="/cs/deque">双端队列</a> 与<a href="/cs/amortized-analysis">摊还</a> 在命令式数组上已出现。函数式不能原地改链表头尾而不影响旧版本。本课不旋转 BST。缺口是双列表队列：<code>front</code> 与 <code>rear</code>（rear 逆序存），倒栈维持平衡。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单链表：入队若只改尾，旧版本的尾无法共享地接上新节点而不改变旧队列。入队全在头则 FIFO 变 LIFO。Hood–Melville / Okasaki：维护两个列表 \\(f,r\\)，不变量常 \\(|r|\\le|f|\\)（变体多）。入队：cons 到 \\(r\\)。出队：从 \\(f\\) 头拿；若 \\(f\\) 空则 reverse \\(r\\) 成新 \\(f\\)。缺口是<strong>倒栈次数被长度摊还</strong>，且每次操作返回新对 \\((f&#39;,r&#39;)\\)，旧对仍可用。</p><p><span class="marginnote">Okasaki <em>JFP</em> 1995 与专著。惰性流可把 reverse 渐进执行，最坏也 \\(O(1)\\) 步（更细）。本课先钉摊还双栈。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>snoc(x)</code>：<code>(f, x::r)</code>，若违不变量则 <code>rotate</code>。<code>head</code>/<code>tail</code> 走 \\(f\\)。持久：cons 共享前缀，reverse 产生新链，旧 \\(r\\) 仍在。</p><p><span class="marginnote">把 rear 想成收件箱、front 想成发件箱：新信只往收件箱顶上放，旧信只从发件箱顶上取；发件箱空了，才把收件箱整摞倒扣过来当新发件箱。倒扣虽慢，但攒了多少封就只用倒这一次。</span></p><p><span class="marginnote">术语翻译：「持久」（persistent）不是存到硬盘，而是指旧版本依然完好可用——你拿到昨天的队列对象，它还是昨天的样子，新操作返回的全新队列不会碰它一根毫毛。</span></p>',10)),(o(),l(E,null,{default:r(()=>[i(s,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20LR%0A%20%20ENQ%5B%22%E5%85%A5%E9%98%9F%22%5D%20--%3E%20REAR%5B%22rear%20%E6%A0%88%22%5D%0A%20%20DEQ%5B%22%E5%87%BA%E9%98%9F%22%5D%20--%3E%20FRONT%5B%22front%20%E6%A0%88%22%5D%0A%20%20REV%5B%22rear%20%E5%80%92%E5%85%A5%20front%22%5D%20--%3E%20AM%5B%22%E6%91%8A%E8%BF%98%20O(1)%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"与 Michael–Scott 无锁队列：那是命令式共享内存；本课不可变。与 Rope：Rope 是随机访问序列，队列只端点。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"势能 \\(|r|\\) 或类似，倒栈花 \\(\\Theta(|r|)\\) 时势能下降。实时变体用惰性，避免单次峰值——若实时路径不能倒整个 \\(r\\)，用 Okasaki 的流。不要用函数式队列当高性能 SPSC 环（那是数组 + 原子）。",-1)),a[6]||(a[6]=e("p",null,"倒栈贵在哪里、为什么摊还后仍是 \\(O(1)\\)？把 \\(|r|\\) 当存钱罐：入队每存一封就投一枚硬币，倒栈时恰好用这些硬币付清。",-1)),(o(),l(E,null,{default:r(()=>[i(s,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20LR%0A%20%20S1%5B%22snoc%20a%EF%BC%9Ar%3D%EF%BC%88a%EF%BC%89%EF%BC%8C%E5%AD%98%201%20%E6%9E%9A%22%5D%20--%3E%20S2%5B%22snoc%20b%EF%BC%9Ar%3D%EF%BC%88b%2C%20a%EF%BC%89%EF%BC%8C%E5%AD%98%202%20%E6%9E%9A%22%5D%20--%3E%20S3%5B%22snoc%20c%EF%BC%9Ar%3D%EF%BC%88c%2C%20b%2C%20a%EF%BC%89%EF%BC%8C%E5%AD%98%203%20%E6%9E%9A%22%5D%0A%20%20S3%20--%3E%20DEQ%5B%22%E5%87%BA%E9%98%9F%EF%BC%9Af%20%E5%B7%B2%E7%A9%BA%22%5D%0A%20%20DEQ%20--%3E%20REV%5B%22reverse%20r%EF%BC%8C%E8%8A%B1%203%20%E6%AD%A5%22%5D%0A%20%20BANK%5B%22%E6%AD%A4%E5%89%8D%203%20%E6%AC%A1%E5%85%A5%E9%98%9F%E5%90%84%E6%8A%95%201%20%E6%9E%9A%22%5D%20--%3E%20REV%0A%20%20REV%20--%3E%20NEWF%5B%22%E6%96%B0%20f%3D%EF%BC%88a%2C%20b%2C%20c%EF%BC%89%EF%BC%8C%E5%AD%98%E9%92%B1%E7%BD%90%E6%B8%85%E9%9B%B6%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=n('<p><span class="marginnote">常见误区：初学者容易以为「出队可能撞上倒栈，所以出队是 \\(O(n)\\)」。实际上倒栈之后 front 就有了一大截存货，接下来很多次出队都只是取头；摊还起来，倒栈的 \\(n\\) 步被之前的 \\(n\\) 次入队分摊，每次平摊 \\(O(1)\\)。</span></p><p>下一课缓存无关：换的是递归布局与 I/O 模型，不必持久。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把实时 deque 的全部旋转写完。无锁进度是后课 CAS 队列。磁盘 B 树的缓存有关分析与 cache-oblivious 对偶，下一课。</p><p>后课默认：持久 FIFO 用双栈/惰性队列。最优缓存利用不依赖 \\(B\\) 参数的结构，用缓存无关模型。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>函数式队列：两栈，倒栈摊还 \\(O(1)\\)，版本共享。</li><li>惰性可消峰值。</li><li>下一课 I/O 与递归布局。</li><li>出处：Okasaki, <em>JFP</em>, 1995 与专著；Hood and Melville。</li></ul>',7))])}const k=d(B,[["render",A]]);export{h as __pageData,k as default};
